import { MakeLogicType, actions, connect, kea, path, reducers, selectors } from 'kea'
import { actionToUrl, router, urlToAction } from 'kea-router'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { urls } from 'scenes/urls'

import { ReplayTabs } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface playlistFiltersLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    activeCategory: string
    activeFilterTab: string
    isExpanded: boolean
    isFiltersExpanded: boolean
    templatesInFiltersPanel: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface playlistFiltersLogicActions {
    setActiveCategory: (categoryId: string) => {
        categoryId: string
    }
    setActiveFilterTab: (activeFilterTab: string) => {
        activeFilterTab: string
    }
    setIsExpanded: (isExpanded: boolean) => {
        isExpanded: boolean
    }
    setIsFiltersExpanded: (isFiltersExpanded: boolean) => {
        isFiltersExpanded: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface playlistFiltersLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        templatesInFiltersPanel: (featureFlags: FeatureFlagsSet) => boolean
    }
}

export type playlistFiltersLogicType = MakeLogicType<
    playlistFiltersLogicValues,
    playlistFiltersLogicActions,
    Record<string, any>,
    playlistFiltersLogicMeta
>

export const playlistFiltersLogic = kea<playlistFiltersLogicType>([
    path(['scenes', 'session-recordings', 'playlist', 'playlistFiltersLogic']),
    connect(() => ({
        values: [featureFlagLogic, ['featureFlags']],
    })),
    actions({
        setIsExpanded: (isExpanded: boolean) => ({ isExpanded }), // WIll be removed together with Mix (R.I.P. Mix)
        setIsFiltersExpanded: (isFiltersExpanded: boolean) => ({ isFiltersExpanded }),
        setActiveFilterTab: (activeFilterTab: string) => ({ activeFilterTab }),
        setActiveCategory: (categoryId: string) => ({ categoryId }),
    }),
    reducers({
        isExpanded: [
            false,
            {
                setIsExpanded: (_, { isExpanded }) => isExpanded,
            },
        ],
        isFiltersExpanded: [
            false,
            {
                setIsFiltersExpanded: (_, { isFiltersExpanded }) => isFiltersExpanded,
            },
        ],
        activeFilterTab: [
            'filters',
            {
                setActiveFilterTab: (_, { activeFilterTab }) => activeFilterTab,
            },
        ],
        activeCategory: [
            'browse' as string,
            {
                setActiveCategory: (_, { categoryId }) => categoryId,
            },
        ],
    }),
    selectors({
        templatesInFiltersPanel: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet) =>
                featureFlags[FEATURE_FLAGS.REPLAY_TEMPLATES_IN_FILTERS_PANEL_EXPERIMENT] === 'test',
        ],
    }),
    urlToAction(({ actions }) => ({
        [urls.replay(ReplayTabs.Home)]: (_, searchParams) => {
            if (searchParams.filtersTab && ['filters', 'saved', 'templates'].includes(searchParams.filtersTab)) {
                actions.setActiveFilterTab(searchParams.filtersTab)
            }
            if (searchParams.showFilters) {
                actions.setIsFiltersExpanded(true)
            }
        },
        [urls.replay(ReplayTabs.Playlists)]: () => {
            actions.setIsFiltersExpanded(false)
        },
    })),
    actionToUrl(({ values }) => ({
        setIsFiltersExpanded: () => {
            if (values.isFiltersExpanded === false) {
                const newSearchParams = new URLSearchParams(router.values.currentLocation.search)
                newSearchParams.delete('showFilters')
                newSearchParams.delete('filtersTab')
                return [
                    router.values.currentLocation.pathname,
                    newSearchParams.toString(),
                    router.values.currentLocation.hashParams,
                ]
            }
        },
    })),
])
